if (k == 0 || points.empty()) {
    return result;
}
std::size_t const need = std::min(k, points.size());

std::vector<std::pair<double, std::size_t>> distIdx;
distIdx.reserve(points.size());

for (std::size_t i = 0; i < points.size(); ++i) {
    double const dx = points[i].x - searchPoint.x;
    double const dy = points[i].y - searchPoint.y;
    double const dz = points[i].z - searchPoint.z;
    double const d2 = dx * dx + dy * dy + dz * dz;
    distIdx.emplace_back(d2, i);
}

std::nth_element(distIdx.begin(),
                 distIdx.begin() + need,
                 distIdx.end(),
                 [](auto const& a, auto const& b) { return a.first < b.first; });

distIdx.resize(need);
std::sort(distIdx.begin(),
          distIdx.end(),
          [](auto const& a, auto const& b) { return a.first < b.first; });

result.reserve(need);
for (auto const& p : distIdx) {
    result.push_back(p.second);
}
return result;

